import os,sys,time
import numpy as np
import mujoco
import rcb_dtb
from scipy.spatial.transform import Rotation as R
from PIL import Image
np.set_printoptions(precision=4,suppress=True)
class Controller:
 def __init__(self):
  self.s=rcb_dtb.Session();self.m=self.s.model;self.d=self.s.data;self.k=mujoco.MjData(self.m);self.bid=self.m.body('palmleft_hand_C_MC').id
  self.s.record_start();self.q=self.s.targets.copy()
 def pose(self): return self.d.xpos[self.bid].copy(), self.d.xmat[self.bid].reshape(3,3).copy()
 def obj(self):return self.d.xpos[self.s._obj].copy(),self.d.xmat[self.s._obj].reshape(3,3).copy()
 def ik(self,p,r,q=None):
  q=self.q.copy() if q is None else q.copy(); jp=np.zeros((3,self.m.nv));jr=jp.copy()
  for _ in range(70):
   self.k.qpos[self.s._jq]=q;mujoco.mj_forward(self.m,self.k)
   e=np.r_[p-self.k.xpos[self.bid],R.from_matrix(r@self.k.xmat[self.bid].reshape(3,3).T).as_rotvec()]
   if np.linalg.norm(e)<1e-5:break
   mujoco.mj_jacBody(self.m,self.k,jp,jr,self.bid);J=np.r_[jp[:,self.s._jv[:7]],jr[:,self.s._jv[:7]]]
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   q[:7]+=dq*np.minimum(1,.12/(np.max(np.abs(dq))+1e-9));q=np.clip(q,self.s.lower+.0001,self.s.upper-.0001)
  return q
 def step(self,q):self.q=q.copy();return self.s.step(q)
 def move(self,p,r,hand=None,n=120):
  p0,r0=self.pose();rot=R.from_matrix(r@r0.T).as_rotvec();h0=self.q[7:].copy()
  for i in range(n):
   a=(i+1)/n;a=a*a*(3-2*a)
   q=self.ik(p0+(p-p0)*a,R.from_rotvec(rot*a).as_matrix()@r0)
   if hand is not None:q[7:]=h0*(1-a)+hand*a
   self.step(q)
 def hold(self,n=60):
  for _ in range(n):self.step(self.q)
 def shot(self,name):
  renderer=mujoco.Renderer(self.m,720,960);cam=mujoco.MjvCamera();cam.lookat[:]=self.obj()[0];cam.distance=.65;cam.azimuth=125;cam.elevation=-25
  renderer.update_scene(self.d,cam);Image.fromarray(renderer.render()).save('/app/output/'+name+'.png');renderer.close()
 def report(self):
  print('step',self.s.steps,'progress',self.s.progress(),'obj',self.obj()[0],'palm',self.pose()[0],flush=True)
  for i in range(self.d.ncon):
   c=self.d.contact[i];b1,b2=self.m.geom_bodyid[[c.geom1,c.geom2]]
   if self.s._obj in [b1,b2]: print('contact',self.m.body(b1).name,self.m.body(b2).name,'dist',c.dist,flush=True)
 def save(self):
  a=self.s.record_stop();self.s.save_trajectory(a);return a

def hand(f=.8,p=1.2,d=.8,thumb=[1.2,0,.6,0,.8]):return np.array(thumb+[f,0,p,d]*3+[0,f,0,p,d],float)

def grasp(c,xoff=0,z=.04,depth=.125,close=None):
 s=c.s
 c.hold(30);op,orr=c.obj();pp,pr=c.pose()
 target=op-pr@np.array([z,xoff,depth]);high=target+np.array([0,0,.10])
 c.move(high,pr,n=120)
 c.move(target,pr,n=150)
 c.shot('pregrasp');c.report()
 c.move(target,pr,hand=hand() if close is None else close,n=180)
 c.hold(100);c.shot('closed');c.report()
 c.move(target+np.array([0,0,.15]),pr,n=240);c.hold(60);c.shot('lift');c.report()
 return c
if __name__=='__main__':
 c=Controller();grasp(c);c.save()
